// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { CopyIcon } from 'lucide-react'

import { DemoStage, PanelChrome, type Build } from '@/app/demos/stage'

import {
  CAPTIONS,
  FIXED,
  FIXED_RESULT,
  FN,
  KEYS,
  PERCENT,
  PERCENT_RESULT,
  ROOT,
  ROOT_KEYS,
  ROOT_RESULT,
  ROOT_TYPED,
  TYPO,
  TYPO_ERROR,
} from './script'

const ROW = 28

const build: Build = ({ tl, q, step, final, move, click, type, wait, cursorOut }) => {
  const flash = (name: string) => {
    tl.fromTo(
      q(name),
      { scale: 0.9 },
      { scale: 1, duration: 0.3, ease: 'back.out(3)', immediateRender: false },
      '<',
    )
  }
  const showResult = (value: string) => {
    tl.set(q('result-value'), { text: value }, '<')
    tl.to(q('error'), { opacity: 0, duration: 0.15 }, '<')
    tl.to(q('result'), { opacity: 1, duration: 0.2 }, '<')
  }
  const clear = () => {
    move('clear')
    click('clear')
    flash('clear')
    tl.set([q('expr-text'), q('expr-more')], { text: '' }, '<')
    tl.to([q('result'), q('error')], { opacity: 0, duration: 0.15 }, '<')
  }

  step(0)
  move('input', { at: 0.3, ax: 0.2 })
  click('input')
  type('expr-text', PERCENT.expr, { speed: 0.05 })
  showResult(PERCENT_RESULT)
  tl.fromTo(
    q('enter'),
    { opacity: 0, y: 4 },
    { opacity: 1, y: 0, duration: 0.2, immediateRender: false },
    '+=0.3',
  )
  tl.to(q('enter'), { opacity: 0, duration: 0.2 }, '+=0.5')
  tl.fromTo(
    q('hist-1'),
    { opacity: 0, x: -8 },
    { opacity: 1, x: 0, duration: 0.3, immediateRender: false },
    '<',
  )
  tl.set(q('history'), { opacity: 1 }, '<')
  tl.set(q('expr-text'), { text: PERCENT_RESULT }, '<')

  step(1, '+=0.5')
  clear()
  ROOT_KEYS.forEach((key, offset) => {
    const index = KEYS.indexOf(key)
    move(`key-${index}`)
    click(`key-${index}`)
    flash(`key-${index}`)
    tl.set(q('expr-text'), { text: ROOT_KEYS.slice(0, offset + 1).join('') }, '<')
  })
  type('expr-more', ROOT_TYPED, { speed: 0.07, at: '+=0.1' })
  showResult(ROOT_RESULT)
  move('eq', { at: '+=0.2' })
  click('eq')
  flash('eq')
  tl.to(q('hist-1'), { y: 0, duration: 0.3, ease: 'power2.inOut' }, '<')
  tl.fromTo(
    q('hist-0'),
    { opacity: 0, x: -8 },
    { opacity: 1, x: 0, duration: 0.3, immediateRender: false },
    '<0.1',
  )
  tl.set(q('expr-text'), { text: ROOT_RESULT }, '<')
  tl.set(q('expr-more'), { text: '' }, '<')

  step(2, '+=0.5')
  clear()
  move('input', { ax: 0.2 })
  click('input')
  type('expr-text', TYPO, { speed: 0.06 })
  tl.set(q('error-text'), { text: TYPO_ERROR }, '<0.2')
  tl.to(q('error'), { opacity: 1, duration: 0.2 }, '<')
  type('expr-more', FIXED.slice(TYPO.length), { at: '+=0.8' })
  showResult(FIXED_RESULT)
  move('hist-1', { at: '+=0.5', ax: 0.3 })
  click('hist-1')
  flash('hist-1')
  tl.set(q('expr-text'), { text: PERCENT.expr }, '<')
  tl.set(q('expr-more'), { text: '' }, '<')
  showResult(PERCENT_RESULT)
  cursorOut('+=0.4')
  final()
  wait(1.2)

  tl.set(
    [q('result'), q('error'), q('enter'), q('history'), q('hist-0'), q('hist-1')],
    { opacity: 0 },
    0,
  )
  tl.set(q('hist-1'), { y: -ROW }, 0)
  tl.set([q('expr-text'), q('expr-more')], { text: '' }, 0)
}

export default function Demo() {
  return (
    <DemoStage
      label={`Calculator evaluating ${PERCENT.expr}, then ${ROOT} from the keypad, then flagging a missing bracket and recalling an answer from history`}
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="flex h-full gap-3">
          <div className="flex w-[270px] shrink-0 flex-col gap-1.5">
            <div className="relative flex items-center gap-1">
              <span
                data-d="input"
                className="flex h-7 min-w-0 flex-1 items-center rounded-md border border-line-strong bg-canvas/80 px-2 font-mono text-[11px] text-ink"
              >
                <span data-d="expr-text" className="whitespace-pre" />
                <span data-d="expr-more" className="whitespace-pre" />
                <span className="ml-px h-3.5 w-px animate-pulse bg-ink-soft" />
              </span>
              <span
                data-d="eq"
                className="flex h-7 w-7 items-center justify-center rounded-md bg-ink text-[12px] font-semibold text-canvas"
              >
                =
              </span>
              <span
                data-d="clear"
                className="flex h-7 w-7 items-center justify-center rounded-md text-[11px] font-semibold text-ink-soft"
              >
                C
              </span>
              <span
                data-d="enter"
                className="absolute -bottom-4 left-24 rounded border border-line-strong bg-elevated px-1.5 py-px font-mono text-[8.5px] text-ink opacity-0 shadow-lg"
              >
                Enter ↵
              </span>
            </div>
            <div className="relative h-9">
              <div
                data-d="result"
                className="absolute inset-0 flex items-center justify-between rounded-md border border-line bg-ink/[0.04] px-2.5 opacity-0"
              >
                <code
                  data-d="result-value"
                  className="font-mono text-[15px] font-semibold text-ink"
                />
                <CopyIcon className="size-3 text-muted" />
              </div>
              <div
                data-d="error"
                className="absolute inset-0 flex items-center rounded-md border border-[#f87171]/40 bg-[#f87171]/10 px-2.5 opacity-0"
              >
                <span data-d="error-text" className="text-[10px] text-[#fca5a5]" />
              </div>
            </div>
            <div className="grid grid-cols-4 gap-1">
              {KEYS.map((key, index) => (
                <span
                  key={key}
                  data-d={`key-${index}`}
                  className="flex h-[23px] items-center justify-center rounded-md border border-line-strong bg-ink/[0.04] font-mono text-[10.5px] text-ink"
                >
                  {key}
                </span>
              ))}
            </div>
          </div>
          <div className="flex min-w-0 flex-1 flex-col gap-2">
            <div className="flex flex-wrap gap-1">
              {FN.map((fn) => (
                <span
                  key={fn}
                  className="rounded px-1.5 py-0.5 font-mono text-[9.5px] text-ink-soft hover:bg-ink/10"
                >
                  {fn}
                </span>
              ))}
            </div>
            <div data-d="history" className="border-t border-line pt-2 opacity-0">
              <div className="flex flex-col gap-1">
                {[
                  { expr: ROOT, result: ROOT_RESULT },
                  { expr: PERCENT.expr, result: PERCENT_RESULT },
                ].map((entry, index) => (
                  <span
                    key={entry.expr}
                    data-d={`hist-${index}`}
                    className="flex h-6 items-center justify-between gap-2 rounded-md bg-ink/[0.04] px-2 font-mono text-[9.5px] tabular-nums opacity-0"
                  >
                    <span className="truncate text-muted">{entry.expr}</span>
                    <span className="shrink-0 text-ink">= {entry.result}</span>
                  </span>
                ))}
              </div>
            </div>
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
